import{_ as t,o,c as s,a0 as d}from"./chunks/framework.CI7OaYtj.js";const g=JSON.parse('{"title":"useRequest 组合式请求 hook 设计规格","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-10-13-useRequest-design.md","filePath":"superpowers/specs/2026-10-13-useRequest-design.md"}'),a={name:"superpowers/specs/2026-10-13-useRequest-design.md"};function n(l,e,c,r,i,p){return o(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="userequest-组合式请求-hook-设计规格" tabindex="-1">useRequest 组合式请求 hook 设计规格 <a class="header-anchor" href="#userequest-组合式请求-hook-设计规格" aria-label="Permalink to &quot;useRequest 组合式请求 hook 设计规格&quot;">​</a></h1><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><code>src/http</code> 目前只有命令式 Promise API：<code>http.get&lt;T&gt;()</code> / <code>post</code> / <code>request</code> / <code>upload</code> / <code>downloadFile</code>，配 <code>abortHttp(requestKey)</code> / <code>abortAllHttp()</code> / <code>clearCache(fingerprint)</code>。错误已由 <code>responded.onSuccess</code> 拆包、<code>defaultBusinessAfterError</code> 统一弹 toast，返回的就是业务数据。</p><p>但这套 API <strong>不提供任何请求状态</strong>。页面想显示「加载中」只有自己写：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const loading = ref&lt;boolean&gt;(false);</span></span>
<span class="line"><span>loading.value = true;</span></span>
<span class="line"><span>http.get&lt;User&gt;(&#39;/user/info&#39;).then((data) =&gt; {</span></span>
<span class="line"><span>  loading.value = false;</span></span>
<span class="line"><span>  user.value = data;</span></span>
<span class="line"><span>}, (err) =&gt; {</span></span>
<span class="line"><span>  loading.value = false;</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>全仓翻下来，「<code>xxxLoading = ref&lt;boolean&gt;(false)</code> + 手动翻转」这一范式散落在 3 个页面、共 6 处：</p><table tabindex="0"><thead><tr><th style="text-align:left;">位置</th><th style="text-align:left;">变量</th></tr></thead><tbody><tr><td style="text-align:left;"><code>src/sub/httpBasicDemo/httpBasicDemo.uvue:406</code></td><td style="text-align:left;"><code>loading</code></td></tr><tr><td style="text-align:left;"><code>src/sub/httpBasicDemo/httpBasicDemo.uvue:411</code></td><td style="text-align:left;"><code>cloudLoading</code></td></tr><tr><td style="text-align:left;"><code>src/sub/httpBasicDemo/httpBasicDemo.uvue:414</code></td><td style="text-align:left;"><code>uploadLoading</code></td></tr><tr><td style="text-align:left;"><code>src/sub/httpBasicDemo/httpBasicDemo.uvue:418</code></td><td style="text-align:left;"><code>downloadLoading</code></td></tr><tr><td style="text-align:left;"><code>src/sub/nestedScrollFunctionDemo/nestedScrollFunctionDemo.uvue:259</code></td><td style="text-align:left;"><code>articleLoading</code></td></tr><tr><td style="text-align:left;"><code>src/sub/zpagingFunctionDemo/zpagingFunctionDemo.uvue:272</code></td><td style="text-align:left;"><code>isLoadMoreLoading</code></td></tr></tbody></table><p>也就是说这个样板是「谁需要谁手写」，没有统一形态，也就没人处理竞态、重复请求、卸载后写状态这些问题。</p><p>本设计新增 <strong><code>src/http/hooks/useRequest.uts</code></strong>，对标 Alova 的 <code>useRequest</code>，把「请求状态机 + 发起/取消/刷新 + 生命周期回调」收进一个组合式 hook。</p><h3 id="_1-1-目标" tabindex="-1">1.1 目标 <a class="header-anchor" href="#_1-1-目标" aria-label="Permalink to &quot;1.1 目标&quot;">​</a></h3><ul><li>页面不再手写 <code>loading</code> / <code>data</code> / <code>error</code> 三件套与 try/finally。</li><li>统一处理并发竞态、失败重试、轮询、防抖、卸载清理——这些是手写版本几乎必然写错的地方。</li><li>形态对齐 Alova，降低熟悉 Alova 的开发者的迁移成本。</li></ul><h3 id="_1-2-非目标-明确不做" tabindex="-1">1.2 非目标（明确不做） <a class="header-anchor" href="#_1-2-非目标-明确不做" aria-label="Permalink to &quot;1.2 非目标（明确不做）&quot;">​</a></h3><ul><li>不做缓存层（<code>cacheFor</code> / <code>staleTime</code> / <code>force</code> / <code>update</code>）。<code>src/http</code> 自带的是「同指纹在飞去重」，不是响应缓存；本版不引入响应缓存，因此这一族选项全部落空。</li><li>不做中间件体系与 <code>useSerialRequest</code> / <code>useWatcher</code> / <code>usePagination</code>。</li><li>不做 <code>downloading</code> / <code>uploading</code> 进度状态（只对上传下载有意义，需要额外接 <code>getTask</code> / <code>onProgressUpdate</code>）。</li></ul><hr><h2 id="_2-对标范围" tabindex="-1">2. 对标范围 <a class="header-anchor" href="#_2-对标范围" aria-label="Permalink to &quot;2. 对标范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Alova <code>useRequest</code> 能力</th><th style="text-align:left;">本版</th><th style="text-align:left;">理由</th></tr></thead><tbody><tr><td style="text-align:left;">基础状态 / 基础用法</td><td style="text-align:left;">✅</td><td style="text-align:left;">核心诉求</td></tr><tr><td style="text-align:left;"><code>immediate: false</code> 关闭自动请求</td><td style="text-align:left;">✅</td><td style="text-align:left;">语义等同我们原本设想的 <code>manual</code>，命名对齐 Alova</td></tr><tr><td style="text-align:left;"><code>initialData</code> 静态初始值</td><td style="text-align:left;">✅</td><td style="text-align:left;">避免每次渲染都要判 <code>null</code></td></tr><tr><td style="text-align:left;"><code>initialData</code> 传函数（同步读缓存做骨架屏）</td><td style="text-align:left;">✅ 但<strong>拆成两个字段</strong></td><td style="text-align:left;">UTS 只支持与 <code>null</code> 的联合，<code>T | null | (() =&gt; T | null)</code> 写不出来；<code>any</code> + 运行时 <code>typeof</code> 判断会丢类型且在鸿蒙端有额外约束</td></tr><tr><td style="text-align:left;"><code>send(...args)</code> 可变参</td><td style="text-align:left;">✅</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">参数在 handler 里接收</td><td style="text-align:left;">✅ 走 <code>ctx.args</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">事件回调里能拿到 <code>event.args</code></td><td style="text-align:left;">✅</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">回调做成「绑定函数」而非配置项</td><td style="text-align:left;">✅</td><td style="text-align:left;">顺带解决「必须先解构出 ref 才能引用」的顺序问题</td></tr><tr><td style="text-align:left;"><code>abort()</code></td><td style="text-align:left;">✅</td><td style="text-align:left;">用 <code>ctx.requestKey</code> 委托 <code>abortHttp</code>。注意 GET 去重命中时只有逻辑取消，见 4.8</td></tr><tr><td style="text-align:left;"><code>force</code>（绕过缓存强制请求）</td><td style="text-align:left;">❌</td><td style="text-align:left;">语义依附缓存，本版无缓存，落地即空转</td></tr><tr><td style="text-align:left;"><code>downloading</code> / <code>uploading</code></td><td style="text-align:left;">❌</td><td style="text-align:left;">非目标</td></tr><tr><td style="text-align:left;"><code>update()</code>（改缓存做乐观更新）</td><td style="text-align:left;">❌</td><td style="text-align:left;">非目标</td></tr><tr><td style="text-align:left;">中间件 <code>middleware</code></td><td style="text-align:left;">❌</td><td style="text-align:left;">非目标；且 UTS 里中间件链的异质签名与 <code>useSerialRequest</code> 是同一块硬骨头</td></tr><tr><td style="text-align:left;"><code>useFetcher</code> 的 <code>fetching</code></td><td style="text-align:left;">❌ 改名 <code>refreshing</code></td><td style="text-align:left;">Alova 的 <code>fetching</code> 是 <code>useFetcher</code> 里 <code>loading</code> 的<strong>同义词</strong>（官方原话：「fetching 的效果与 loading 相同」），价值依附「只刷缓存、不返回 data」，与本 hook 无关。我们保留「区分首次加载 / 刷新中」这个真需求，但改名为 <code>refreshing</code>，避免同名不同义</td></tr></tbody></table><hr><h2 id="_3-api-契约" tabindex="-1">3. API 契约 <a class="header-anchor" href="#_3-api-契约" aria-label="Permalink to &quot;3. API 契约&quot;">​</a></h2><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// ===== 顶层 type 别名 =====</span></span>
<span class="line"><span>// 剩余参数不能内联写在对象类型的属性上（UTS 语法报错），必须先抽成顶层别名再挂上去</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/** 可变参发送函数；被 abort / 竞态丢弃时 resolve null */</span></span>
<span class="line"><span>export type UseRequestSender&lt;T&gt; = (...args: Array&lt;any&gt;) =&gt; Promise&lt;T | null&gt;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/** 三个生命周期回调解收到的统一事件对象 */</span></span>
<span class="line"><span>export type UseRequestEvent&lt;T&gt; = {</span></span>
<span class="line"><span>  args: Array&lt;any&gt;;      // 本次 send 的参数</span></span>
<span class="line"><span>  data: T | null;        // 成功时有值，其余为 null</span></span>
<span class="line"><span>  error: Error | null;   // 失败时有值，其余为 null</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/** 回调绑定函数：调用它才完成绑定 */</span></span>
<span class="line"><span>export type UseRequestBinder&lt;T&gt; = (cb: (event: UseRequestEvent&lt;T&gt;) =&gt; void) =&gt; void;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export type UseRequestContext = {</span></span>
<span class="line"><span>  requestKey: string;    // 交给 extra.requestKey，abort() 才能真取消</span></span>
<span class="line"><span>  args: Array&lt;any&gt;;      // send(1, 2, 3) 传进来的参数</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export type UseRequestOptions&lt;T&gt; = {</span></span>
<span class="line"><span>  immediate?: boolean;              // 默认 true：setup 后自动发一次（无参）</span></span>
<span class="line"><span>  initialData?: T | null;           // 静态初始值，默认 null</span></span>
<span class="line"><span>  initialDataFn?: () =&gt; T | null;   // 同步求初始值（如从 storage 读）；两者都给时以 initialDataFn 为准</span></span>
<span class="line"><span>  debounce?: number;                // 毫秒，默认 0（关闭）</span></span>
<span class="line"><span>  retry?: number;                   // 失败重试次数，默认 0</span></span>
<span class="line"><span>  retryDelay?: number;              // 重试间隔毫秒，默认 0</span></span>
<span class="line"><span>  polling?: number;                 // 轮询间隔毫秒，默认 0（关闭）</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export type UseRequestResult&lt;T&gt; = {</span></span>
<span class="line"><span>  data: Ref&lt;T | null&gt;;</span></span>
<span class="line"><span>  loading: Ref&lt;boolean&gt;;      // 有请求在飞（含首次）</span></span>
<span class="line"><span>  refreshing: Ref&lt;boolean&gt;;   // loading &amp;&amp; data != null，即「已有内容时的刷新中」</span></span>
<span class="line"><span>  error: Ref&lt;Error | null&gt;;</span></span>
<span class="line"><span>  send: UseRequestSender&lt;T&gt;;</span></span>
<span class="line"><span>  abort: () =&gt; void;</span></span>
<span class="line"><span>  refresh: () =&gt; Promise&lt;T | null&gt;;   // 用上一次的 args 重发</span></span>
<span class="line"><span>  onSuccess: UseRequestBinder&lt;T&gt;;</span></span>
<span class="line"><span>  onError: UseRequestBinder&lt;T&gt;;</span></span>
<span class="line"><span>  onComplete: UseRequestBinder&lt;T&gt;;</span></span>
<span class="line"><span>  startPolling: () =&gt; void;</span></span>
<span class="line"><span>  stopPolling: () =&gt; void;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export function useRequest&lt;T&gt;(</span></span>
<span class="line"><span>  fn: (ctx: UseRequestContext) =&gt; Promise&lt;T&gt;,</span></span>
<span class="line"><span>  options?: UseRequestOptions&lt;T&gt; | null</span></span>
<span class="line"><span>): UseRequestResult&lt;T&gt;</span></span></code></pre></div><p>用法：</p><div class="language-uts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">uts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const { data, loading, refreshing, error, send, abort, onSuccess, onError } = useRequest&lt;Article&gt;(</span></span>
<span class="line"><span>  (ctx) =&gt; http.get&lt;Article&gt;(\`/article/\${ctx.args[0]}\`, {</span></span>
<span class="line"><span>    extra: { requestKey: ctx.requestKey }</span></span>
<span class="line"><span>  }),</span></span>
<span class="line"><span>  { immediate: false, retry: 2, debounce: 300 }</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>onSuccess((event) =&gt; { console.log(&#39;拿到了&#39;, event.data?.title, &#39;参数&#39;, event.args); });</span></span>
<span class="line"><span>onError((event) =&gt; { console.log(&#39;挂了&#39;, event.error?.message); });</span></span>
<span class="line"><span></span></span>
<span class="line"><span>send(1024);   // 触发</span></span></code></pre></div><p><code>startPolling</code> / <code>stopPolling</code> 是我们自己加的（Alova 把轮询放在 middleware 里，本版没有 middleware），供页面在切 tab、离开页面等时机手动停轮询用。</p><hr><h2 id="_4-状态与语义" tabindex="-1">4. 状态与语义 <a class="header-anchor" href="#_4-状态与语义" aria-label="Permalink to &quot;4. 状态与语义&quot;">​</a></h2><h3 id="_4-1-状态定义" tabindex="-1">4.1 状态定义 <a class="header-anchor" href="#_4-1-状态定义" aria-label="Permalink to &quot;4.1 状态定义&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">状态</th><th style="text-align:left;">定义</th></tr></thead><tbody><tr><td style="text-align:left;"><code>loading</code></td><td style="text-align:left;">有一次请求在飞（含首次、重试、轮询）</td></tr><tr><td style="text-align:left;"><code>refreshing</code></td><td style="text-align:left;"><code>loading == true</code> 且 <code>data != null</code>。页面据此把「首次加载」渲染成骨架屏、把「刷新中」渲染成小转圈，而不会把已有内容换掉</td></tr><tr><td style="text-align:left;"><code>data</code></td><td style="text-align:left;">最后一次<strong>被采纳</strong>的响应数据；<code>abort</code> / 竞态丢弃不写入</td></tr><tr><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">每次请求<strong>开始</strong>时置 <code>null</code>，失败时写入本次的 <code>Error</code>。于是「<code>error != null</code>」恒等于「最后一次请求失败了」，无需额外判断。<code>abort()</code> 不额外改动它（该请求开始时就已清空，取消后就保持 <code>null</code>）</td></tr></tbody></table><h3 id="_4-2-并发竞态-必须处理" tabindex="-1">4.2 并发竞态（必须处理） <a class="header-anchor" href="#_4-2-并发竞态-必须处理" aria-label="Permalink to &quot;4.2 并发竞态（必须处理）&quot;">​</a></h3><p>内部维护自增代次 <code>seq</code>。每次 <code>send</code> / <code>refresh</code> / 轮询触发都 <code>seq++</code> 并捕获本次的值，响应回来时<strong>只有捕获值等于当前 <code>seq</code> 才写状态</strong>（<code>data</code> / <code>error</code> / <code>loading</code> 同理）。这样连续触发时「先发后到」的旧响应会被丢弃，<code>loading</code> 也由最新一次决定，不会被旧请求提前置回 <code>false</code>。</p><h3 id="_4-3-重试" tabindex="-1">4.3 重试 <a class="header-anchor" href="#_4-3-重试" aria-label="Permalink to &quot;4.3 重试&quot;">​</a></h3><ul><li><code>retry: n</code> 表示失败后最多再试 <code>n</code> 次，间隔 <code>retryDelay</code>。</li><li><strong>只重试网络层失败</strong>。判据：<code>err instanceof BusinessError</code> 直接放弃重试（业务码错误重试纯属浪费），主动 <code>abort</code> 也不重试。这个判据与既有实现一致——<code>src/http/request/request.uts:199</code> 判断是否吞掉 toast 用的就是同一个 <code>instanceof</code>，说明跑到 hook 手里的错误确实是这个类，不需要再包一层归一。</li><li>重试期间保持 <code>loading</code>，不重新进入 <code>refreshing</code> 的翻转过程。</li></ul><h3 id="_4-4-轮询" tabindex="-1">4.4 轮询 <a class="header-anchor" href="#_4-4-轮询" aria-label="Permalink to &quot;4.4 轮询&quot;">​</a></h3><ul><li><code>polling &gt; 0</code> 时启用；<code>immediate: false</code> 的场景下不自动开始，需调 <code>startPolling()</code>。</li><li><strong>轮询不把 <code>loading</code> 置 <code>true</code></strong>，否则页面会一直转圈。</li><li>轮询失败：不写 <code>error</code>、不触发 <code>onError</code>、不重试，等下一个周期。（<strong>toast 不在此列</strong>——toast 由 <code>src/http</code> 的 <code>defaultBusinessAfterError</code> 统一决定，hook 既不弹也管不了。轮询场景想安静，需要在业务侧自己处理 <code>afterError</code> 钩子。这一点是本版的一个已知缺口，不在本次范围内解决。）</li><li>卸载时自动 <code>stopPolling</code>；<code>stopPolling()</code> 幂等，未在轮询时调用是空操作。</li></ul><h3 id="_4-5-abort-与卸载" tabindex="-1">4.5 abort 与卸载 <a class="header-anchor" href="#_4-5-abort-与卸载" aria-label="Permalink to &quot;4.5 abort 与卸载&quot;">​</a></h3><ul><li><code>abort()</code> = 顶掉代次 <code>seq</code>（后续响应作废，含「已入队但还没触发的防抖」）+ <code>abortHttp(ctx.requestKey)</code> 取消底层请求 + <code>loading = false</code>。<strong>「取消底层请求」这一步在 GET 去重命中时不生效</strong>，此时只有 <code>seq</code> 守卫提供的逻辑取消——见 4.8。</li><li><strong><code>abort()</code> 不触发 <code>onError</code></strong>（取消不是错误），但<strong>触发 <code>onComplete</code></strong>（对齐 Alova）。<code>onComplete</code> 收到的 event 里 <code>data</code> 与 <code>error</code> <strong>都是 <code>null</code></strong>——据此可把「被取消」与「成功」「失败」区分开。</li><li><code>send()</code> 被 abort / 竞态丢弃时 resolve <code>null</code>。</li><li><code>abort()</code> 在没有请求在飞时是空操作（仍然触发一次 <code>onComplete</code>）。</li><li><code>refresh()</code> 用上一次的 <code>args</code> 重发；若从未 <code>send</code> 过（例如 <code>immediate: false</code> 且还没手动发），等价于 <code>send()</code> 无参发起一次。</li><li>页面 <code>onUnmounted</code> 时自动：置 <code>disposed</code> 标记 → <code>abort()</code> → <code>stopPolling()</code>。<code>disposed</code> 标记用于挡住「防抖延迟到卸载之后才触发」的那一次。</li></ul><h3 id="_4-6-防抖" tabindex="-1">4.6 防抖 <a class="header-anchor" href="#_4-6-防抖" aria-label="Permalink to &quot;4.6 防抖&quot;">​</a></h3><p>复用 <code>uni_modules/lime-shared</code> 的 <code>debounce</code>（遵守红线 42，不手写通用工具），引入形态照抄项目内既有用法：<code>import { debounce } from &#39;@/uni_modules/lime-shared/debounce&#39;;</code>（见 <code>src/sub/limeSharedFunctionDemo/limeSharedFunctionDemo.uvue:292</code>）。两平台签名不一致（APP 版单参、Web 版 <code>...args</code>），统一按「传一个 <code>Array&lt;any&gt;</code>」的方式调用即可兼容。</p><p><strong>已知短板</strong>：该库版本没有 <code>cancel()</code> / <code>flush()</code>，卸载后那次 pending 触发无法从外部取消。因此：</p><ul><li>卸载后：<code>disposed</code> 守卫把它变成空操作（不会真发请求）。</li><li><code>abort()</code> 后：靠代次 <code>seq</code> 作废（触发时发现捕获的代次已过期，直接 return）。</li></ul><p>两者合起来覆盖了「取消」的全部实际需求，因此<strong>不引入本地自写防抖</strong>。</p><h3 id="_4-7-immediate-的触发时机" tabindex="-1">4.7 <code>immediate</code> 的触发时机 <a class="header-anchor" href="#_4-7-immediate-的触发时机" aria-label="Permalink to &quot;4.7 \`immediate\` 的触发时机&quot;">​</a></h3><p><code>immediate: true</code>（默认）时，首次请求在 <code>useRequest()</code> <strong>被调用的当下同步发起</strong>（即在 <code>setup</code> 期间），而不是等到 <code>onMounted</code>——与 Alova 一致，也让请求尽早并行于首屏渲染。</p><p><code>polling &gt; 0</code> 时，<strong>首次请求同样在 setup 当下发出</strong>（与 <code>immediate</code> 一致，不额外等一个 <code>polling</code> 间隔），之后每隔 <code>polling</code> 毫秒发一次。定时器用 <code>setInterval</code> 持有 id，<code>stopPolling()</code> 清掉；卸载清理走 <code>onUnmounted</code> 注册。</p><h3 id="_4-8-与-http-层-get-去重的交互-重要约束" tabindex="-1">4.8 与 http 层 GET 去重的交互（重要约束） <a class="header-anchor" href="#_4-8-与-http-层-get-去重的交互-重要约束" aria-label="Permalink to &quot;4.8 与 http 层 GET 去重的交互（重要约束）&quot;">​</a></h3><p><code>client.uts:684-691</code> 有一条既有行为：<strong>GET 请求默认按指纹去重</strong>，指纹是 <code>method|url|JSON.stringify(data)</code>（<code>lifecycle.uts:216-229</code>），命中时<strong>直接复用同一份在飞 Promise，不再发新请求</strong>；开关是 <code>extra.dedupe</code>，只有显式传 <code>false</code> 才关。注意指纹里<strong>不含 <code>requestKey</code></strong>。</p><p>对 hook 有两个直接后果，必须在实现里正面处理，不能等运行时才发现：</p><ol><li><p><strong><code>abort()</code> 在去重命中时退化为空转。</strong> 第二次 <code>send</code> 走的是 <code>return pending</code>（<code>client.uts:689</code>），根本不会执行到登记 <code>extra.requestKey</code> 的那段（<code>client.uts:381-384</code>）。于是 <code>abortHttp(第二次的 requestKey)</code> 打在一个从未登记过的键上——底层请求照跑不停。 <strong>应对</strong>：不指望 <code>abortHttp</code> 兜住这种情况，状态正确性由 <code>seq</code> 代次守卫保证（迟到的响应写不进 <code>data</code> / <code>loading</code>）。也就是说「取消」在这条路径上是<strong>逻辑取消</strong>（状态不再变化），不是<strong>网络取消</strong>。这一点写进文档而不是藏着。</p></li><li><p><strong><code>refresh()</code> 在去重命中时不会真的重发。</strong> 同名 GET 还在飞时点刷新，拿回的是同一份 Promise。对「避免重复流量」是好事，但和 Alova「refresh 必定重发」的直觉不同，页面写轮询/刷新时必须知道。 <strong>应对</strong>：连 <code>immediate: true</code> 的首发在内，hook 自己<strong>不去动 <code>dedupe</code> 开关</strong>（那是调用方在 <code>extra</code> 里的地盘，hook 不该覆盖）。需要在某次调用上强制重发的，由调用方自己传 <code>extra: { dedupe: false }</code>。这条约束写进 hook 的文件头注释。</p></li><li><p>去重只作用于 <strong>GET</strong>（<code>client.uts:685</code> 的 <code>isGet &amp;&amp;</code>），POST / PUT / DELETE 不受影响，<code>abort()</code> 在这些方法上是真取消。</p></li></ol><h3 id="_4-9-send-的失败策略-与-alova-的一处刻意偏离" tabindex="-1">4.9 <code>send()</code> 的失败策略（与 Alova 的一处刻意偏离） <a class="header-anchor" href="#_4-9-send-的失败策略-与-alova-的一处刻意偏离" aria-label="Permalink to &quot;4.9 \`send()\` 的失败策略（与 Alova 的一处刻意偏离）&quot;">​</a></h3><p>Alova 的 <code>send()</code> 在失败时 reject。本版<strong>不 reject，失败也 resolve <code>null</code></strong>，错误只走 <code>error</code> 状态与 <code>onError</code> 绑定函数。</p><p>理由：<code>src/http</code> 已经统一弹过 toast，多数调用方不关心失败；而原生端一个没人 <code>catch</code> 的 rejected promise 会变成 unhandled rejection，比 H5 更难排查。代价是 <code>await send()</code> 拿到 <code>null</code> 时分不清「失败」还是「被取消/竞态丢弃」——要区分看 <code>error</code> 状态。</p><hr><h2 id="_5-落位与依赖" tabindex="-1">5. 落位与依赖 <a class="header-anchor" href="#_5-落位与依赖" aria-label="Permalink to &quot;5. 落位与依赖&quot;">​</a></h2><ul><li>新增 <code>src/http/hooks/useRequest.uts</code>（类型与实现同文件；类型不拆 <code>.ts</code>——红线 20 禁止跨分支共享类型经 <code>.ts</code> 转发）。</li><li>门面：<code>src/http/index.uts</code> 增加一条 <code>export * from &#39;./hooks/useRequest.uts&#39;;</code>。同一顶层符号只在这一层门面转发（红线 15/36），且 hook 内部<strong>精准导入</strong> <code>../request/request.uts</code> 这个具体实现文件而非 <code>index.uts</code>，不构成自环。</li><li>依赖：<code>vue</code>（<code>ref</code> / <code>onUnmounted</code> / <code>Ref</code> 类型）、<code>lime-shared/debounce</code>、<code>../request/request.uts</code>（<code>http</code>、<code>abortHttp</code>）、<code>../error/error.uts</code>（<code>BusinessError</code>）。</li><li>文件体积预期 250~350 行。若超过 400 行，再把「防抖 + 重试 + 轮询」抽成 <code>src/http/hooks/internal/scheduler.uts</code>。</li></ul><hr><h2 id="_6-uts-风险点与验证顺序" tabindex="-1">6. UTS 风险点与验证顺序 <a class="header-anchor" href="#_6-uts-风险点与验证顺序" aria-label="Permalink to &quot;6. UTS 风险点与验证顺序&quot;">​</a></h2><p>按风险从高到低，<strong>实现的第一步是先写一个最小骨架并跑真编译</strong>，骨架通过再往里填逻辑——这四项任何一项不成立都要改 API 形态，晚发现等于返工。</p><ol><li><strong>泛型 + <code>type</code> 字面量赋值</strong>：<code>const result: UseRequestResult&lt;T&gt; = { ... }</code> 这种「泛型实例化 + 对象字面量赋值」是整个设计的最大风险点，Kotlin 端行为未知。</li><li><strong>红线 41</strong>：断言里绝不能出现泛型实例化<strong>别名</strong>，只能直写本体。返回处一律用「先声明带类型标注的变量再 <code>return</code>」，不用 <code>as</code>。</li><li><strong>红线 25</strong>：<code>send</code> 的剩余参数必须走顶层 <code>type UseRequestSender&lt;T&gt;</code> 别名，不能内联声明在结果对象的属性上。</li><li><strong><code>lime-shared/debounce</code> 的解析</strong>：项目内现成用法是目录形态导入，但那是 <code>.uvue</code>；<code>.uts</code> 里是否同样解析成功未经验证。失败则改用显式 <code>debounce/index.ts</code> 路径。</li><li><strong><code>Ref&lt;T | null&gt;</code> 泛型嵌套</strong>在 Kotlin 端的表现。</li></ol><p>验证命令：<code>pnpm dev:app-android</code>（真编译，看 <code>unpackage/cache/.app-android/src/index.kt</code> 是否生成并通过）+ <code>pnpm test</code>（单测，走 esbuild 转译，<strong>不复现</strong>上面第 1~3 条的 Kotlin 层风险，所以两者都要跑）。</p><hr><h2 id="_7-测试计划" tabindex="-1">7. 测试计划 <a class="header-anchor" href="#_7-测试计划" aria-label="Permalink to &quot;7. 测试计划&quot;">​</a></h2><p>新增 <code>tests/unit/api/use-request.test.ts</code>（与既有 <code>http.test.ts</code> / <code>http-stream.test.ts</code> 同目录）。底层用假 <code>uni.request</code> 拦截，沿用 <code>tests/unit/api/http-stream.test.ts</code> 里 <code>installFakeRequest()</code> 的写法（捕获入参、暴露 resolve/reject 入口、可 abort）。</p><p>覆盖点（都是手写版本几乎必然写错的地方）：</p><ol><li>状态机基本流转：<code>loading</code> 翻转、成功写 <code>data</code>、失败写 <code>error</code>、绑定回调收到正确 <code>event</code>。</li><li><strong>并发竞态</strong>：连续两次 <code>send</code>，第二次先返回、第一次后返回 → <code>data</code> 必须是第二次的，且第一次的迟到响应不覆盖。</li><li>重试：网络错误重试 <code>n</code> 次后成功；<code>BusinessError</code> <strong>不</strong>重试；<code>retry: 0</code> 时不重试。</li><li>防抖：连续 <code>send(a)</code> / <code>send(b)</code> / <code>send(c)</code> 只发一次，且参数是最后那次。</li><li>轮询：<code>polling</code> 期间 <code>loading</code> 不翻转；<code>stopPolling</code> 后不再发；轮询失败不写 <code>error</code>。</li><li><code>abort()</code>：底层 <code>requestKey</code> 被 <code>abortHttp</code> 取消、<code>onError</code> <strong>不</strong>触发、<code>onComplete</code> 触发（<code>data</code>/<code>error</code> 均为 <code>null</code>）、<code>send()</code> resolve <code>null</code>。</li><li><strong>去重交互（4.8）</strong>：同参数 GET 连续 <code>send</code> 两次，断言底层只发出<strong>一次</strong>请求（<code>uni.request</code> 调用计数），且 <code>abort()</code> 后迟到的响应仍不写 <code>data</code>；再断言传 <code>extra: { dedupe: false }</code> 时确实发两次。这条要用真实 <code>createHttpClient</code> 而非裸 promise stub，否则测不到去重层。</li><li>卸载：<code>onUnmounted</code> 后迟到的响应与 pending 防抖都不再写状态（不产生「已卸载组件仍更新」）。</li><li><code>initialData</code> / <code>initialDataFn</code> 的取值优先级。</li></ol><hr><h2 id="_8-示例页改动" tabindex="-1">8. 示例页改动 <a class="header-anchor" href="#_8-示例页改动" aria-label="Permalink to &quot;8. 示例页改动&quot;">​</a></h2><p><code>src/sub/httpBasicDemo/httpBasicDemo.uvue</code> 现有 5 张卡（第 1 张 uniCloud 云对象、第 2 张 Mock 列表、第 3 张「真实接口请求状态」、第 4 张文件上传、第 5 张文件下载）。在其末尾追加第 6 张卡「useRequest 组合式请求」，沿用该页既有的卡片容器类（<code>rounded-[16px] p-[20px] m-[16px] border-[1px] border-solid border-[#edf2f7] bg-[#ffffff]</code>）与卡头注释条风格（<code>&lt;!-- ============ N. 标题 ============ --&gt;</code>）。</p><p>内容：</p><ul><li>请求示例展示 <code>loading</code> / <code>data</code> / <code>error</code> 三种渲染分支，并把 <code>refreshing</code> 单独渲染出来以示区别。</li><li>可点按钮分别触发：<code>send</code> 带参、<code>refresh</code>、<code>abort</code>、<code>stopPolling</code>。</li><li>防抖输入框（连续输入只发一次）与轮询开关。</li></ul><p><strong>定位</strong>：第 3 张卡已经在手写 <code>loading = ref&lt;boolean&gt;(false)</code> 那套（见 1. 概述的表），新卡是它的对照——同一件事用 hook 写。第 3 张卡<strong>不改动</strong>，保留手写形态作为对比样本。</p><p>页面按规约写 <code>definePage</code>（<code>layout: &#39;navbar&#39;</code>、<code>enablePullDownRefresh: true</code>）——该页已有此配置，只做增量追加。</p><hr><h2 id="_9-交付清单" tabindex="-1">9. 交付清单 <a class="header-anchor" href="#_9-交付清单" aria-label="Permalink to &quot;9. 交付清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">项</th><th style="text-align:left;">文件</th></tr></thead><tbody><tr><td style="text-align:left;">hook 本体</td><td style="text-align:left;"><code>src/http/hooks/useRequest.uts</code>（新增）</td></tr><tr><td style="text-align:left;">门面导出</td><td style="text-align:left;"><code>src/http/index.uts</code>（+1 行）</td></tr><tr><td style="text-align:left;">单元测试</td><td style="text-align:left;"><code>tests/unit/api/use-request.test.ts</code>（新增）</td></tr><tr><td style="text-align:left;">示例</td><td style="text-align:left;"><code>src/sub/httpBasicDemo/httpBasicDemo.uvue</code>（追加一节）</td></tr></tbody></table>`,72)])])}const h=t(a,[["render",n]]);export{g as __pageData,h as default};
